#!/usr/bin/env python3

"""Autogenerated RPC error codes"""

import enum


class RPCError(enum.IntEnum):
    """RPC error codes"""

    # RPC protocol and request validation errors.
    INVALID_COMMAND = -1000
    MALFORMED_REQUEST = -1001
    INVALID_ARGUMENT = -1002
    UNSUPPORTED_REQUEST = -1003
    RESPONSE_BUFFER_TOO_SMALL = -1004

    # Device and generic data availability errors.
    DEVICE_NOT_FOUND = -1020
    DEVICE_NOT_READY = -1021
    NO_DATA = -1022

    # Data payload and data logger errors.
    DATA_OUT_OF_RANGE = -1040
    DATA_LENGTH_MISMATCH = -1041
    DATA_CRC_MISMATCH = -1042
    DATA_READ_FAILED = -1043
    DATA_WRITE_FAILED = -1044
    DATA_ERASE_FAILED = -1045
    DATA_FLUSH_FAILED = -1046
    DATA_VALIDATE_FAILED = -1047
    DATA_VARIANCE_TOO_HIGH = -1048
    DATA_RECEIVE_FAILED = -1049
    DATA_ALIGNMENT_ERROR = -1050

    # File system errors.
    FILE_ALREADY_PRESENT = -1060
    FILE_NOT_FOUND = -1061
    FILE_TOO_SMALL = -1062
    FILE_OPEN_FAILED = -1063
    FILE_CREATE_FAILED = -1064
    FILE_DELETE_FAILED = -1065
    FILE_CLOSE_FAILED = -1066
    FILE_READ_FAILED = -1067
    FILE_WRITE_FAILED = -1068
    FILE_SEEK_FAILED = -1069
    FILE_SIZE_FAILED = -1070
    FILE_METADATA_FAILED = -1071
    FILE_CRC_FAILED = -1072
    FILE_ITERATION_FAILED = -1073

    # Flash storage errors.
    FLASH_AREA_OPEN_FAILED = -1080
    FLASH_AREA_CLOSE_FAILED = -1081
    FLASH_ERASE_FAILED = -1082
    FLASH_READ_FAILED = -1083
    FLASH_WRITE_FAILED = -1084
    FLASH_FLUSH_FAILED = -1085
    FLASH_CRC_FAILED = -1086
    FLASH_DATA_TOO_LARGE = -1087

    # Streaming, DFU, and patch application errors.
    STREAM_INIT_FAILED = -1100
    DFU_PREPARE_FAILED = -1101
    DFU_FINISH_FAILED = -1102
    DFU_REBOOT_FAILED = -1103
    PATCH_ORIGINAL_OPEN_FAILED = -1104
    PATCH_OUTPUT_OPEN_FAILED = -1105
    PATCH_OUTPUT_ERASE_FAILED = -1106
    PATCH_VALIDATE_FAILED = -1107
    PATCH_APPLY_FAILED = -1108

    # Bluetooth transport errors.
    BT_NOT_CONNECTED = -1120
    BT_CONNECT_FAILED = -1121
    BT_CONNECTION_TIMEOUT = -1122
    BT_DISCONNECT_FAILED = -1123
    BT_COMMAND_QUEUE_FAILED = -1124
    BT_NO_INITIAL_ACK = -1125
    BT_TIMEOUT_UPDATE_FAILED = -1126
    BT_RESPONSE_TIMEOUT = -1127
    BT_REMOTE_ERROR = -1128
    BT_CHARACTERISTIC_NOT_FOUND = -1129
    BT_GATT_WRITE_FAILED = -1130
    BT_FILE_LENGTH_MISMATCH = -1131
    BT_FILE_CRC_MISMATCH = -1132

    # Modem AT command errors.
    MODEM_AT_UNSAFE = -1140
    MODEM_AT_FAILED = -1141
    MODEM_AT_CANCELLED = -1142
    MODEM_AT_TIMEOUT = -1143
    MODEM_AT_BUSY = -1144

    # Network, socket, and CoAP errors.
    NETWORK_INTERFACE_NOT_FOUND = -1160
    NETWORK_SCAN_START_FAILED = -1161
    NETWORK_INTERFACE_UP_FAILED = -1162
    DNS_QUERY_FAILED = -1163
    SOCKET_CREATE_FAILED = -1164
    SOCKET_CONFIG_FAILED = -1165
    SOCKET_CONNECT_FAILED = -1166
    COAP_DOWNLOAD_FAILED = -1167

    # Security key and access protection errors.
    AUTHENTICATION_REQUIRED = -1180
    READ_PROTECTED = -1181
    WRITE_PROTECTED = -1182
    CRYPTO_FAILED = -1183
    KEY_ACTION_UNSUPPORTED = -1184
    KEY_ID_UNSUPPORTED = -1185
    KEY_WRITE_FORBIDDEN = -1186
    KEY_RESET_FAILED = -1187
    KEY_DELETE_FAILED = -1188
    KEY_WRITE_FAILED = -1189

    # Key-value store errors.
    KV_KEY_NOT_ENABLED = -1200
    KV_KEY_NOT_FOUND = -1201
    KV_READ_FAILED = -1202
    KV_WRITE_FAILED = -1203
    KV_DELETE_FAILED = -1204
    KV_REFLECT_FAILED = -1205
    KV_WRITE_REJECTED = -1206

    # Zbus channel errors.
    CHANNEL_NOT_FOUND = -1220
    CHANNEL_NO_DATA = -1221
    CHANNEL_READ_FAILED = -1222

    # Time and GNSS errors.
    TIME_SET_FAILED = -1240
    GNSS_POWER_UP_FAILED = -1241
    GNSS_POLL_UNIQUE_ID_FAILED = -1242
    GNSS_POLL_VERSION_FAILED = -1243
    GNSS_UNEXPECTED_PAYLOAD = -1244


__all__ = [
    "RPCError",
]
